const r = $input.first().json || {};
if (!r.topic) return [{ json: { response: 'Сохранённых разборов по этой теме нет. Если нужен новый — клиент может запустить /research (это тратит суточный лимит и токены).' } }];
return [{ json: { response: 'Нашёл сохранённый разбор «' + r.topic + '» (' + r.on_date + '). Саммари: ' + (r.summary || '') + '

Полный текст отчёта:
' + (r.report_text || '') + '

Это готовый разбор из памяти — новый /research запускать не нужно.' } }];
